import { formatUsd, toUnits, type Company, type Intake, type Invoice } from "shared";

const notice =
  "TEMPLATE generated by opencash from the founder's formation answers. It is not legal advice. Have a lawyer licensed in the relevant state review it before relying on it.";

const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

function longDate(ms: number): string {
  return new Date(ms).toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric", timeZone: "UTC" });
}

function signatureBlock(parties: string[]): string {
  return [
    "SIGNATURES",
    "Each party signs by sending sign_agreement for this document's SHA-256 hash from their own NEAR account to the opencash registry contract. The signing account, the block time and the document hash recorded on NEAR are the signature.",
    "",
    ...parties.map((p) => `Signed by NEAR account: ${p}`),
  ].join("\n");
}

export function operatingAgreement(intake: Intake, company: Company, parties: string[], nowMs: number): string {
  const name = intake.company.names[0];
  const members = intake.llc.members;
  const managed = intake.llc.management === "manager" ? "managers appointed by a majority in interest of the Members" : "its Members";
  return [
    notice,
    "",
    `OPERATING AGREEMENT OF ${name.toUpperCase()}`,
    "A Wyoming Limited Liability Company",
    `Effective ${longDate(nowMs)}`,
    "",
    "1. FORMATION. The Members form the Company under the Wyoming Limited Liability Company Act (W.S. 17-29-101 et seq.). If this Agreement conflicts with a provision of the Act that the Members may vary, this Agreement controls.",
    `2. NAME AND PURPOSE. The Company's name is ${name}. Its purpose is: ${intake.company.description}, and any other lawful business.`,
    "3. REGISTERED AGENT AND OFFICE. The Company keeps a registered agent and office in Wyoming as listed in its Articles of Organization.",
    `4. MEMBERS AND OWNERSHIP. The Members and their ownership percentages are:\n${members.map((m) => `   - ${m.name}: ${m.ownership_pct}%`).join("\n")}`,
    `5. MANAGEMENT. The Company is managed by ${managed}. Decisions outside the ordinary course of business need the approval of Members holding more than 50% of the ownership percentages.`,
    "6. CAPITAL. No Member must contribute additional capital. Contributions made are recorded in the Company's books.",
    "7. ALLOCATIONS AND DISTRIBUTIONS. Profits, losses and distributions are allocated in proportion to ownership percentages. Distributions are made when the Members decide, provided the Company can still pay its debts as they come due.",
    `8. TAX. The Company is taxed as ${members.length === 1 ? "a disregarded entity" : "a partnership"} unless the Members elect otherwise. Its fiscal year ends in ${months[intake.company.fiscal_year_end_month - 1]}.`,
    "9. TRANSFERS. A Member may not transfer an ownership interest without the written consent of the other Members, except to the Company.",
    "10. LIABILITY AND INDEMNIFICATION. No Member or manager is personally liable for the Company's obligations solely because of that role. The Company indemnifies Members and managers for acts taken in good faith on its behalf, except for fraud, gross negligence or willful misconduct.",
    "11. DISSOLUTION. The Company dissolves on the written decision of Members holding more than 50% of the ownership percentages, or as required by the Act.",
    "12. ELECTRONIC SIGNATURES AND RECORDS. The Members agree to sign and keep this Agreement electronically under the federal E-SIGN Act and the Wyoming Uniform Electronic Transactions Act.",
    "13. GOVERNING LAW. Wyoming law governs this Agreement.",
    "",
    `Company NEAR account: ${company.account_id}`,
    "",
    signatureBlock(parties),
  ].join("\n");
}

export function bylaws(intake: Intake, company: Company, parties: string[], nowMs: number): string {
  const name = intake.company.names[0];
  const k = intake.corp;
  return [
    notice,
    "",
    `BYLAWS OF ${name.toUpperCase()}`,
    "A Delaware Corporation",
    `Adopted ${longDate(nowMs)}`,
    "",
    "ARTICLE I. OFFICES. The registered office is in the State of Delaware, as stated in the Certificate of Incorporation. The Corporation may have other offices anywhere.",
    "ARTICLE II. STOCKHOLDERS. An annual meeting elects directors. Special meetings may be called by the board or the President. A majority of the outstanding shares entitled to vote is a quorum. Stockholders may act by written or electronic consent as permitted by the Delaware General Corporation Law (DGCL).",
    `ARTICLE III. DIRECTORS. The business is managed by a board of ${k.directors.length} director(s): ${k.directors.join(", ")}. A majority of directors is a quorum. The board may act by unanimous written or electronic consent.`,
    `ARTICLE IV. OFFICERS. The officers are a President (${k.president}), a Secretary (${k.secretary}) and a Treasurer (${k.treasurer}). One person may hold several offices. Officers serve at the pleasure of the board.`,
    `ARTICLE V. STOCK. The Corporation is authorized to issue ${k.authorized_shares.toLocaleString("en-US")} shares of common stock, par value $${k.par_value}. Initial holders:\n${k.shareholders.map((s) => `   - ${s.name}: ${s.ownership_pct}% of initially issued shares`).join("\n")}`,
    "ARTICLE VI. INDEMNIFICATION. The Corporation indemnifies its directors and officers to the fullest extent the DGCL permits.",
    `ARTICLE VII. FISCAL YEAR. The fiscal year ends in ${months[intake.company.fiscal_year_end_month - 1]}.`,
    "ARTICLE VIII. ELECTRONIC SIGNATURES AND RECORDS. Consents, notices and records may be given, signed and kept electronically, as permitted by DGCL § 116 and the federal E-SIGN Act.",
    "ARTICLE IX. AMENDMENTS. The board or the stockholders may amend these Bylaws.",
    "",
    `Company NEAR account: ${company.account_id}`,
    "",
    signatureBlock(parties),
  ].join("\n");
}

export function serviceAgreement(company: Company, invoice: Invoice, terms: string, parties: string[], nowMs: number): string {
  return [
    notice.replace("from the founder's formation answers", "from an opencash invoice"),
    "",
    "CLIENT SERVICE AGREEMENT",
    `Dated ${longDate(nowMs)}`,
    "",
    `1. PARTIES. ${company.legal_name} ("Provider", NEAR account ${company.account_id}) and ${invoice.client_name} ("Client").`,
    `2. SERVICES. Provider will deliver:\n${invoice.items.map((i) => `   - ${i.description}: ${formatUsd(toUnits(i.amount))}`).join("\n")}`,
    `3. FEES AND PAYMENT. Client pays ${formatUsd(invoice.amount)} under invoice ${invoice.id}, due ${longDate(invoice.due_ms)}. Payment is made through the invoice's opencash pay link. Provider receives USDC on NEAR, where 1 USDC equals 1 US dollar. Client pays its own network and conversion costs.`,
    "4. ADDITIONAL TERMS.",
    terms.trim() ? terms.trim() : "   None.",
    "5. INTELLECTUAL PROPERTY. When the invoice is paid in full, Client owns the deliverables created specifically for Client. Provider keeps its pre-existing tools and know-how.",
    "6. CONFIDENTIALITY. Each party keeps the other's non-public information confidential and uses it only to perform this Agreement.",
    "7. LIABILITY. Except for fraud or willful misconduct, each party's liability is limited to the fees paid under this Agreement.",
    "8. ELECTRONIC SIGNATURES. The parties agree to sign this Agreement electronically under the federal E-SIGN Act.",
    "",
    signatureBlock(parties),
  ].join("\n");
}
